#!/usr/bin/env bash
# Open a pull request that brings electron-host's Electron surface up to the
# newest Electron releases, with the coverage list measured against it.
#
#   .github/scripts/electron-surface-refresh.sh
#
# electron-surface.yml runs it weekly. A new Electron adds APIs apps will
# call; the pull request's coverage.json diff shows each one the host lacks,
# for someone to close or accept. It is not set to merge itself.
#
# Uses DOMICILE_WRITEBACK_TOKEN, because GITHUB_TOKEN cannot open pull requests
# here and its pull requests start no checks.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"

BRANCH="${DOMICILE_SURFACE_BRANCH:-electron-surface-refresh}"
REPO="${GITHUB_REPOSITORY:?GITHUB_REPOSITORY names the repository to open the pull request in}"
GITHUB_API="${DOMICILE_GITHUB_API:-https://api.github.com}"
API="$GITHUB_API/repos/$REPO"
: "${DOMICILE_WRITEBACK_TOKEN:?DOMICILE_WRITEBACK_TOKEN is what pushes and opens the pull request}"
HOST=packages/electron-host
SURFACE="$HOST/src/electron/surface.ts"
COVERAGE="$HOST/src/__integration__/coverage.json"
PRELOAD_COVERAGE="$HOST/src/__integration__/preload-coverage.json"
EVENTS="$HOST/src/__integration__/events.json"

git fetch -q origin main
git checkout -q -B "$BRANCH" origin/main

(cd "$HOST" && bun scripts/electron-surface.ts)
# The generator writes plain JSON; biome sorts and wraps it as the tree has it.
bunx biome check --write "$SURFACE" >/dev/null
(cd "$HOST" && UPDATE_COVERAGE=1 bun test coverage)

# Only the header's list of versions moving, as most patch releases do, adds
# no API: not worth a pull request.
if git diff --quiet -I '^// ' -- "$SURFACE" "$COVERAGE" "$PRELOAD_COVERAGE" "$EVENTS"; then
  echo "no new Electron API since the surface was last made; nothing to land"
  exit 0
fi

covered="$(sed -n '2s|^// \(.*\)\.$|\1|p' "$SURFACE")"
newest="${covered%%,*}"
# Each gap the diff adds (+) or drops (-), a preload's named so.
listed() { # sign
  git diff -U0 -- "$COVERAGE" | sed -n "s/^$1  \"\(.*\)\",\{0,1\}\$/- \`\1\`/p"
  git diff -U0 -- "$PRELOAD_COVERAGE" |
    sed -n "s/^$1  \"\(.*\)\",\{0,1\}\$/- preload \`\1\`/p"
  git diff -U0 -- "$EVENTS" |
    sed -n "s/^$1    \"\([^\"]*\)\": .*/- event \`\1\`/p"
}
gaps="$(listed +)"
closed="$(listed -)"

cat >.changeset/electron-surface-refresh.md <<MD
---
"@domicile-desktop/electron-host": patch
---

electron-host's Electron surface covers Electron $newest.
MD

export GIT_AUTHOR_NAME="domicile CI"
export GIT_AUTHOR_EMAIL="ci@domicile.invalid"
export GIT_COMMITTER_NAME="domicile CI"
export GIT_COMMITTER_EMAIL="ci@domicile.invalid"

git add "$SURFACE" "$COVERAGE" "$PRELOAD_COVERAGE" "$EVENTS" .changeset/electron-surface-refresh.md
git commit -q -m "$(cat <<MSG
Cover Electron $newest in electron-host's surface

Generated by packages/electron-host/scripts/electron-surface.ts from the
electron.d.ts of Electron $covered, and coverage.json,
preload-coverage.json and events.json measured against it,
by electron-surface.yml.

Release-notes: none
MSG
)"

# The empty value clears the checkout's header before this one is added.
auth="$(printf 'x-access-token:%s' "$DOMICILE_WRITEBACK_TOKEN" | base64 | tr -d '\n')"
git -c http.https://github.com/.extraheader= \
  -c "http.https://github.com/.extraheader=AUTHORIZATION: basic $auth" \
  push -q -f origin "$BRANCH"

body="$(cat <<MD
electron-surface.yml regenerated the surface from Electron $covered.

APIs the host or the engine's preload lacks, and events the host never fires, that this adds to coverage.json, preload-coverage.json or events.json, each a gap an app on the new Electron can hit:

${gaps:-- none}

Gaps that went, as a name Electron dropped:

${closed:-- none}

Close a gap in the host before merging, or merge to accept it as listed.
MD
)"
request="$(jq -cn --arg title "Cover Electron $newest in electron-host's surface" \
  --arg head "$BRANCH" --arg body "$body" \
  '{title: $title, head: $head, base: "main", body: $body}')"
reply="$(mktemp)"
trap 'rm -f "$reply"' EXIT
code="$(curl -sS -o "$reply" -w '%{http_code}' -X POST -d "$request" \
  -H "Authorization: Bearer $DOMICILE_WRITEBACK_TOKEN" \
  -H "Accept: application/vnd.github+json" "$API/pulls")"
case "$code" in
2*) echo "opened #$(jq -r .number "$reply") for Electron $newest" ;;
# Already open from this branch, which the push just brought up to date.
422) echo "the pull request from $BRANCH is open; its branch now covers Electron $newest" ;;
*)
  echo "GitHub answered $code to opening the pull request: $(cat "$reply")" >&2
  exit 1
  ;;
esac
